import React, { createContext, useState, useEffect } from "react";

export const UserContext = createContext(null);

export function UserProvider({ children }) {
  const [profile, setProfile] = useState(() => {
    try {
      const raw = localStorage.getItem("ssp_profile");
      return raw ? JSON.parse(raw) : { completed: false };
    } catch {
      return { completed: false };
    }
  });

  useEffect(() => {
    localStorage.setItem("ssp_profile", JSON.stringify(profile));
  }, [profile]);

  const updateProfile = (patch) => {
    setProfile((prev) => ({ ...prev, ...patch }));
  };

  const resetProfile = () => {
    setProfile({ completed: false });
  };

  return (
    <UserContext.Provider value={{ profile, updateProfile, resetProfile }}>
      {children}
    </UserContext.Provider>
  );
}

