import React from "react";

export default function Stepper({ steps = [], current = 0 }) {
  return (
    <div className="mb-6">
      <div className="flex items-center space-x-2">
        {steps.map((s, i) => {
          const active = i === current;
          const done = i < current;
          return (
            <div key={s} className="flex-1">
              <div className="flex items-center">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center ${done ? 'bg-indigo-600 text-white' : active ? 'bg-indigo-100 text-indigo-700' : 'bg-gray-200 text-gray-600'}`}>
                  {i + 1}
                </div>
                <div className="ml-3 text-sm font-medium text-slate-700">{s}</div>
              </div>
              {i < steps.length - 1 && (
                <div className={`h-1 mt-3 ${done ? 'bg-indigo-600' : 'bg-gray-200'}`} />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

