import React, { useState, useContext } from "react";
import Stepper from "../Stepper";
import Card from "../common/Card";
import Button from "../common/Button";

import BasicInfo from "./steps/BasicInfo";
import LevelSelection from "./steps/LevelSelection";
import PurposeSelection from "./steps/PurposeSelection";
import ConditionalDetails from "./steps/ConditionalDetails";
import { UserContext } from "../../context/UserContext";

const STEPS = ["Basic Info", "Level", "Goal", "Details", "Finish"];

export default function Onboarding() {
  const [step, setStep] = useState(0);
  const { profile, updateProfile } = useContext(UserContext);

  const next = () => setStep((s) => Math.min(s + 1, STEPS.length - 1));
  const prev = () => setStep((s) => Math.max(s - 1, 0));

  const onSubmitStep = (data) => {
    updateProfile(data);
    next();
  };

  const finishOnboarding = () => {
    updateProfile({ completed: true, onboardedAt: new Date().toISOString() });
  };

  return (
    <div className="max-w-3xl mx-auto">
      <Card>
        <Stepper steps={STEPS} current={step} />
        <div className="space-y-6">
          {step === 0 && <BasicInfo initial={profile} onNext={onSubmitStep} />}
          {step === 1 && <LevelSelection initial={profile} onNext={onSubmitStep} onBack={prev} />}
          {step === 2 && <PurposeSelection initial={profile} onNext={onSubmitStep} onBack={prev} />}
          {step === 3 && (
            <ConditionalDetails initial={profile} onNext={onSubmitStep} onBack={prev} />
          )}
          {step === 4 && (
            <div>
              <h3 className="text-lg font-semibold">Review & Finish</h3>
              <pre className="mt-4 bg-gray-50 p-4 rounded-md text-sm overflow-auto">
                {JSON.stringify(profile, null, 2)}
              </pre>
              <div className="mt-4 flex gap-3">
                <Button onClick={finishOnboarding}>Finish and Go to Dashboard</Button>
                <button className="px-4 py-2 rounded-md border" onClick={prev}>Back</button>
              </div>
            </div>
          )}
        </div>
      </Card>
    </div>
  );
}

