import React, { useState } from "react";
import Input from "../../common/Input";
import Button from "../../common/Button";

export default function BasicInfo({ initial = {}, onNext }) {
  const [form, setForm] = useState({
    name: initial.name || "",
    email: initial.email || "",
    password: "",
  });

  const handleChange = (k) => (e) => setForm({ ...form, [k]: e.target.value });

  const submit = (e) => {
    e.preventDefault();
    // Basic validation
    if (!form.name || !form.email || !form.password) return alert("Please fill all fields");
    onNext({ name: form.name, email: form.email, password: form.password });
  };

  return (
    <form onSubmit={submit} className="space-y-4">
      <h3 className="text-lg font-semibold">Basic Information</h3>
      <Input label="Full Name" value={form.name} onChange={handleChange("name")} />
      <Input label="Email" type="email" value={form.email} onChange={handleChange("email")} />
      <Input label="Password" type="password" value={form.password} onChange={handleChange("password")} />
      <div className="flex justify-end">
        <Button type="submit">Next</Button>
      </div>
    </form>
  );
}

