import React, { useState } from "react";
import Select from "../../common/Select";
import Input from "../../common/Input";
import Button from "../../common/Button";

import SchoolDetails from "./substeps/SchoolDetails";
import CollegeDetails from "./substeps/CollegeDetails";
import ProfessionalDetails from "./substeps/ProfessionalDetails";
import SkillDetails from "./substeps/SkillDetails";
import ExamDetails from "./substeps/ExamDetails";
import InterviewDetails from "./substeps/InterviewDetails";

export default function ConditionalDetails({ initial = {}, onNext, onBack }) {
  // initial contains level and purpose
  const level = initial.level;
  const purpose = initial.purpose;

  const [localData, setLocalData] = useState(initial || {});

  const handlePatch = (patch) => {
    setLocalData((s) => ({ ...s, ...patch }));
  };

  const submit = (e) => {
    e?.preventDefault();
    onNext(localData);
  };

  return (
    <form onSubmit={submit} className="space-y-4">
      <h3 className="text-lg font-semibold">Tell us more</h3>

      {/* Level-specific */}
      {level === "School Student" && (
        <SchoolDetails initial={localData} onChange={handlePatch} />
      )}
      {level === "College Student" && (
        <CollegeDetails initial={localData} onChange={handlePatch} />
      )}
      {level === "Working Professional" && (
        <ProfessionalDetails initial={localData} onChange={handlePatch} />
      )}

      {/* Purpose-specific */}
      {purpose === "Learn Skills" && (
        <SkillDetails initial={localData} onChange={handlePatch} />
      )}
      {purpose === "Prepare for Exams" && (
        <ExamDetails initial={localData} onChange={handlePatch} />
      )}
      {purpose === "Prepare for Interviews" && (
        <InterviewDetails initial={localData} onChange={handlePatch} />
      )}

      <div className="flex justify-between mt-3">
        <button type="button" className="px-4 py-2 rounded-md border" onClick={onBack}>Back</button>
        <Button type="submit">Save & Next</Button>
      </div>
    </form>
  );
}

