import React from "react";
import Select from "../../common/Select";

const SUBJECTS = {
  Science: ["Maths", "Physics", "Chemistry", "Biology"],
  Commerce: ["Accounts", "Business Studies", "Economics"],
  Arts: ["History", "Political Science", "Sociology"],
};

export default function SchoolDetails({ initial = {}, onChange }) {
  const cls = initial.class || "";
  const stream = initial.stream || "";

  return (
    <div className="space-y-4">
      <Select label="Class" value={cls} onChange={(e) => onChange({ class: e.target.value })}>
        <option value="">Select class</option>
        {Array.from({ length: 12 }, (_, i) => i + 1).map((c) => (
          <option key={c} value={c}>{c}</option>
        ))}
      </Select>

      {(+cls === 11 || +cls === 12) && (
        <>
          <Select label="Stream" value={stream} onChange={(e) => onChange({ stream: e.target.value })}>
            <option value="">Select stream</option>
            {["Science", "Commerce", "Arts"].map((s) => <option key={s} value={s}>{s}</option>)}
          </Select>

          {stream && (
            <div>
              <label className="text-sm font-medium text-slate-600">Subjects</label>
              <div className="mt-2 flex gap-2 flex-wrap">
                {SUBJECTS[stream].map((sub) => (
                  <span key={sub} className="px-3 py-1 border rounded-full bg-gray-50 text-sm">{sub}</span>
                ))}
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

